// Exception upsert + SLA. Spec sections 6.3, 9.3, 11.

int thisapp.recon.slaHours(string severity)
{
	if(severity == "Critical")
	{
		return 4;
	}
	if(severity == "High")
	{
		return 24;
	}
	if(severity == "Medium")
	{
		return 72;
	}
	return 120;
}


int thisapp.recon.upsertException(int auditID)
{
	aud = Policy_Audit[ID == auditID];
	if(!aud.count())
	{
		return 0;
	}
	verdict = aud.Verdict;
	if(verdict == "clean_match")
	{
		thisapp.recon.maybeAutoClose(aud.Policy, verdict);
		return 0;
	}
	conf = ifnull(aud.Confidence, 0);
	sev = thisapp.recon.severityFor(verdict, aud.Policy, conf);
	hours = thisapp.recon.slaHours(sev);
	opened = zoho.currenttime;
	due = opened.addHour(hours);
	existing = Audit_Exceptions[Policy == aud.Policy && Verdict == verdict && Status in {"Open", "In Progress", "Waiting"}];
	nm = sev + " — " + aud.Policy_Number + " — " + verdict;
	if(existing.count())
	{
		ex = existing;
		ex.Audit=auditID;
		ex.Severity=sev;
		ex.Name=nm;
		if(thisapp.recon.severityRank(sev) > thisapp.recon.severityRank(ex.Severity))
		{
			ex.SLA_Hours=hours;
			ex.SLA_Due_At=due;
		}
		aud.Exception_Created=true;
		aud.Related_Exception=ex.ID;
		return ex.ID;
	}
	ownerEmail = thisapp.recon.defaultOwner(sev);
	row = insert into Audit_Exceptions
	[
		Name=nm
		Policy=aud.Policy
		Policy_Number=aud.Policy_Number
		Audit=auditID
		Verdict=verdict
		Severity=sev
		Status="Open"
		SLA_Hours=hours
		SLA_Due_At=due
		SLA_Breached=false
		Owner=ownerEmail
		Opened_At=opened
		Notify_Sent=false
	];
	aud.Exception_Created=true;
	aud.Related_Exception=row;
	return row;
}


int thisapp.recon.severityRank(string sev)
{
	if(sev == "Critical")
	{
		return 4;
	}
	if(sev == "High")
	{
		return 3;
	}
	if(sev == "Medium")
	{
		return 2;
	}
	return 1;
}


// Assign by role label. Replace with actual Creator user emails in production.

string thisapp.recon.defaultOwner(string severity)
{
	if(severity == "High" || severity == "Critical")
	{
		return "lamar";
	}
	return "gretchen";
}


void thisapp.recon.maybeAutoClose(int policyID, string newVerdict)
{
	if(newVerdict != "clean_match")
	{
		return;
	}
	openRows = Audit_Exceptions[Policy == policyID && Status in {"Open", "In Progress", "Waiting"}];
	for each ex in openRows
	{
		if(ex.Verdict == "pending_sync" || ex.Verdict == "stale_crm")
		{
			ex.Status="Resolved";
			ex.Resolution_Class="Data lag";
			ex.Resolution_Notes="Auto-closed: subsequent audit was clean_match.";
			ex.Resolved_At=zoho.currenttime;
		}
	}
}


// Hourly SLA sweep.

void thisapp.recon.slaSweep()
{
	openRows = Audit_Exceptions[Status in {"Open", "In Progress", "Waiting"} && SLA_Breached == false];
	for each ex in openRows
	{
		if(ex.SLA_Due_At != null && zoho.currenttime > ex.SLA_Due_At)
		{
			ex.SLA_Breached=true;
			thisapp.recon.notifyException(ex.ID, "SLA_Breached");
		}
	}
}


void thisapp.recon.notifyException(int exceptionID, string eventName)
{
	ex = Audit_Exceptions[ID == exceptionID];
	if(!ex.count())
	{
		return;
	}
	if(eventName != "SLA_Breached")
	{
		if(ex.Notify_Sent == true && ex.Last_Notify_At != null)
		{
			ageHours = (zoho.currenttime.toLong() - ex.Last_Notify_At.toLong()) / 3600000;
			if(ex.Severity == "Critical" && ageHours < 24)
			{
				return;
			}
		}
	}
	subj = "[RSG Recon] " + eventName + " " + ex.Severity + " " + ex.Policy_Number + " " + ex.Verdict;
	body = "Policy: " + ex.Policy_Number + "\nVerdict: " + ex.Verdict + "\nSeverity: " + ex.Severity + "\nDue: " + ex.SLA_Due_At;
	// Replace with actual user emails after install.
	sendmail
	[
		from: zoho.adminuserid
		to: zoho.adminuserid
		subject: subj
		message: body
	]
	ex.Notify_Sent=true;
	ex.Last_Notify_At=zoho.currenttime;
	if(ex.Severity == "High" || ex.Severity == "Critical")
	{
		ex.Escalated_To_Lamar=true;
	}
}

// Orchestrator: one policy + daily batch. Spec section 9.

int thisapp.recon.runOne(int policyID, string runType, string runID)
{
	rec = Policy_Master[ID == policyID];
	if(!rec.count())
	{
		return 0;
	}
	if(ifnull(runID, "") == "")
	{
		runID = zoho.currenttime.toString("yyyyMMddHHmmss");
	}
	if(ifnull(runType, "") == "")
	{
		runType = "manual";
	}
	norm = thisapp.recon.normalizeStatus(ifnull(rec.AMS_Status_Raw, rec.Policy_Status));
	if(norm != "" && rec.Policy_Status != norm)
	{
		rec.Policy_Status=norm;
		rec.Active=thisapp.recon.isActiveStatus(norm);
	}
	bt = thisapp.recon.normalizeBilling(ifnull(rec.Billing_Type, ""));
	if(bt != "")
	{
		rec.Billing_Type=bt;
	}
	rec.Policy_Tier=thisapp.recon.computeTier(policyID);
	rw = thisapp.recon.detectRewrite(policyID);
	if(rw.get("detected") == true && rw.get("successor_id") != 0)
	{
		thisapp.recon.applyRewriteLink(policyID);
	}
	thisapp.recon.refreshQueueDerived(policyID);
	scoreMap = thisapp.recon.scoreDetail(policyID);
	vmap = thisapp.recon.verdictDetail(policyID);
	verdict = vmap.get("verdict");
	score = scoreMap.get("score");
	stamp = zoho.currenttime;
	qstale = thisapp.recon.evaluateQueueStaleFromPolicy(policyID);
	prem = rec.Premium;
	crmPrem = rec.CRM_Premium;
	delta = null;
	deltaPct = null;
	if(prem != null && crmPrem != null)
	{
		delta = prem - crmPrem;
		if(crmPrem != 0)
		{
			dabs = delta;
			if(dabs < 0)
			{
				dabs = dabs * -1;
			}
			deltaPct = (dabs / crmPrem) * 100;
		}
	}
	nm = rec.Policy_Number + " @ " + stamp;
	aud = insert into Policy_Audit
	[
		Name=nm
		Policy=policyID
		Policy_Number=rec.Policy_Number
		Run_ID=runID
		Run_At=stamp
		Run_Type=runType
		Verdict=verdict
		Confidence=score
		AMS_Status=thisapp.recon.normalizeStatus(ifnull(rec.AMS_Status_Raw, rec.Policy_Status))
		CRM_Status=thisapp.recon.normalizeStatus(ifnull(rec.CRM_Status, ""))
		Creator_Status=thisapp.recon.normalizeStatus(ifnull(rec.Policy_Status, ""))
		AMS_Premium=prem
		CRM_Premium=crmPrem
		Premium_Delta=delta
		Premium_Delta_Pct=deltaPct
		Queue_Stale=qstale.get("stale")
		Duplicate_Count=scoreMap.get("duplicate_count")
		Rewrite_Linked=if(rec.Rewrite_Of != null, true, false)
		Pending_Queue_Jobs=ifnull(rec.Pending_Queue_Jobs, 0)
		Findings=vmap.get("findings")
		Recommendation=vmap.get("recommendation")
		Score_Breakdown=scoreMap.get("breakdown")
		Exception_Created=false
	];
	rec.Last_Verdict=verdict;
	rec.Last_Confidence=score;
	rec.Last_Audit_Date=stamp;
	rec.Run_Recon_On_Save=false;
	thisapp.recon.upsertException(aud);
	if(verdict != "clean_match")
	{
		ex = Audit_Exceptions[Audit == aud && Status == "Open"];
		if(ex.count() && (ex.Severity == "Critical" || (ex.Severity == "High" && verdict == "missing_in_ams")))
		{
			thisapp.recon.notifyException(ex.ID, "New exception");
		}
	}
	return aud;
}


void thisapp.recon.runDaily()
{
	runID = "daily-" + zoho.currenttime.toString("yyyyMMddHHmmss");
	windowDate = zoho.currentdate.addDay(120);
	targets = Policy_Master[Policy_Tier == "A" || Policy_Tier == "B" || Active == true || Expiration_Date <= windowDate || Last_Verdict != "clean_match" || Last_Audit_Date == null];
	for each rec in targets
	{
		thisapp.recon.runOne(rec.ID, "scheduled_daily", runID);
	}
	thisapp.recon.slaSweep();
}


void thisapp.recon.runWeeklyTierC()
{
	runID = "tierc-" + zoho.currenttime.toString("yyyyMMddHHmmss");
	targets = Policy_Master[Policy_Tier == "C"];
	for each rec in targets
	{
		thisapp.recon.runOne(rec.ID, "scheduled_tier", runID);
	}
}


void thisapp.recon.refreshQueueDerived(int policyID)
{
	q = Renewal_Queue[Policy == policyID && Dismissed == false];
	if(!q.count())
	{
		return;
	}
	for each row in q
	{
		row.Cadence_Bucket=thisapp.recon.cadenceBucket(row.Expiration_Date);
		row.Risk_Status=thisapp.recon.classifyRisk(row.ID);
		st = thisapp.recon.evaluateQueueStale(row.ID);
		row.Stale_Flag=st.get("stale");
		row.Stale_Reason=st.get("reason");
		if(st.get("stale") == true && row.Queue_Status == "Open")
		{
			row.Queue_Status="Stale";
		}
	}
}


string thisapp.recon.cadenceBucket(date exp)
{
	if(exp == null)
	{
		return "";
	}
	days = daysBetween(zoho.currentdate, exp);
	if(days < 0)
	{
		return "Past Due";
	}
	if(days <= 30)
	{
		return "30";
	}
	if(days <= 60)
	{
		return "60";
	}
	if(days <= 90)
	{
		return "90";
	}
	return "";
}


string thisapp.recon.classifyRisk(int queueID)
{
	row = Renewal_Queue[ID == queueID];
	if(!row.count())
	{
		return "SAFE";
	}
	cur = ifnull(row.Premium_Current, 0);
	ren = row.Premium_Renewal;
	if(ren != null && cur > 0)
	{
		inc = ((ren - cur) / cur) * 100;
		if(inc > 15)
		{
			return "CRITICAL";
		}
		if(inc >= 5)
		{
			return "AT_RISK";
		}
	}
	if(row.Expiration_Date == null)
	{
		return "SAFE";
	}
	days = daysBetween(zoho.currentdate, row.Expiration_Date);
	if(days <= 30)
	{
		return "CRITICAL";
	}
	if(days <= 90)
	{
		return "AT_RISK";
	}
	return "SAFE";
}


map thisapp.recon.evaluateQueueStale(int queueID)
{
	out = Map();
	out.put("stale", false);
	out.put("reason", "");
	row = Renewal_Queue[ID == queueID];
	if(!row.count())
	{
		return out;
	}
	pol = Policy_Master[ID == row.Policy];
	pstat = thisapp.recon.normalizeStatus(ifnull(pol.Policy_Status, ""));
	openish = {"Open", "In Progress", "Waiting Client", "Waiting Carrier", "Stale"};
	if(pstat == "Cancelled" || pstat == "Flat Cancel" || pstat == "Rewritten" || pstat == "Renewed" || pstat == "Non-Renewed")
	{
		if(openish.contains(row.Queue_Status))
		{
			out.put("stale", true);
			out.put("reason", "Policy_Status=" + pstat + " but queue still " + row.Queue_Status);
			return out;
		}
	}
	if(pol.Expiration_Date != null && row.Expiration_Date != null && pol.Expiration_Date != row.Expiration_Date)
	{
		out.put("stale", true);
		out.put("reason", "Queue Expiration_Date != Policy_Master Expiration_Date");
		return out;
	}
	ageDays = 0;
	if(row.Last_Touched_At != null)
	{
		ageDays = daysBetween(row.Last_Touched_At.toDate(), zoho.currentdate);
	}
	else
	{
		ageDays = 999;
	}
	bucket = ifnull(row.Cadence_Bucket, thisapp.recon.cadenceBucket(row.Expiration_Date));
	qstat = ifnull(row.Queue_Status, "");
	if((bucket == "30" || bucket == "Past Due") && (qstat == "Open" || qstat == "In Progress") && ageDays > 7)
	{
		out.put("stale", true);
		out.put("reason", "Cadence " + bucket + " untouched " + ageDays + " days");
		return out;
	}
	if(bucket == "60" && qstat == "Open" && ageDays > 14)
	{
		out.put("stale", true);
		out.put("reason", "Cadence 60 Open untouched " + ageDays + " days");
		return out;
	}
	return out;
}


map thisapp.recon.evaluateQueueStaleFromPolicy(int policyID)
{
	q = Renewal_Queue[Policy == policyID && Dismissed == false];
	out = Map();
	out.put("stale", false);
	out.put("reason", "");
	if(!q.count())
	{
		return out;
	}
	return thisapp.recon.evaluateQueueStale(q.ID);
}

// Zoho CRM read (Phase 4). Connection name: zoho_crm
// Custom module API name may be "Policies" or "CustomModuleX" — confirm in
// Settings → APIs → API Names after the CRM field pack is installed
// (docs/zoho/fields_policies.csv).
//
// NEVER create Accounts. NEVER update CRM unless approval gate passes.

void thisapp.recon.pullCRM(int policyID)
{
	rec = Policy_Master[ID == policyID];
	if(!rec.count())
	{
		return;
	}
	guid = ifnull(rec.NowCerts_Policy_GUID, "");
	pnum = ifnull(rec.Policy_Number, "");
	crmRow = null;
	if(guid != "")
	{
		crit = "(NowCerts_Policy_GUID:equals:" + guid + ")";
		resp = zoho.crm.searchRecords("Policies", crit, 1, 2);
		if(resp.size() == 1)
		{
			crmRow = resp.get(0);
		}
		else if(resp.size() > 1)
		{
			rec.Sync_Status="Error";
			rec.Notes=ifnull(rec.Notes, "") + "\n[recon] duplicate CRM Policies for GUID " + guid;
			return;
		}
	}
	if(crmRow == null && pnum != "")
	{
		crit2 = "(Policy_Number:equals:" + pnum + ")";
		resp2 = zoho.crm.searchRecords("Policies", crit2, 1, 2);
		if(resp2.size() == 1)
		{
			crmRow = resp2.get(0);
		}
		else if(resp2.size() > 1)
		{
			rec.Sync_Status="Error";
			rec.Notes=ifnull(rec.Notes, "") + "\n[recon] duplicate CRM Policies for number " + pnum;
			return;
		}
	}
	if(crmRow == null)
	{
		return;
	}
	rec.CRM_Policy_ID=crmRow.get("id");
	acct = crmRow.get("Account_Name");
	if(acct != null && acct.get("id") != null)
	{
		rec.CRM_Account_ID=acct.get("id");
	}
	rec.CRM_Status=thisapp.recon.normalizeStatus(ifnull(crmRow.get("Policy_Status"), ""));
	if(crmRow.get("Premium") != null)
	{
		rec.CRM_Premium=crmRow.get("Premium");
	}
	if(crmRow.get("Modified_Time") != null)
	{
		rec.Last_CRM_Modified=crmRow.get("Modified_Time").toTime("yyyy-MM-dd'T'HH:mm:ss");
	}
	rec.Last_Synced=zoho.currenttime;
	if(ifnull(rec.Sync_Status, "") != "Pending")
	{
		rec.Sync_Status="Synced";
	}
}


void thisapp.recon.pullCRMBatch()
{
	rows = Policy_Master[Active == true || Policy_Tier == "A" || Policy_Tier == "B"];
	for each rec in rows
	{
		thisapp.recon.pullCRM(rec.ID);
	}
}


// GATED WRITE — do not call from schedules.
// Preconditions: Approved_To_Push, Approved_By, Approved_At within 24h,
// latest Policy_Audit.Recommended_Payload non-empty.

map thisapp.recon.pushCRMIfApproved(int policyID)
{
	out = Map();
	out.put("ok", false);
	rec = Policy_Master[ID == policyID];
	if(!rec.count())
	{
		out.put("error", "not found");
		return out;
	}
	if(rec.Approved_To_Push != true || rec.Approved_By == null || rec.Approved_At == null)
	{
		out.put("error", "approval gate failed");
		return out;
	}
	ageHours = (zoho.currenttime.toLong() - rec.Approved_At.toLong()) / 3600000;
	if(ageHours > 24)
	{
		out.put("error", "approval older than 24h");
		return out;
	}
	if(ifnull(rec.CRM_Policy_ID, "") == "")
	{
		out.put("error", "no CRM_Policy_ID — create drafts are human-only");
		return out;
	}
	aud = Policy_Audit[Policy == policyID] sort by Run_At desc range from 0 to 0;
	payloadText = ifnull(aud.Recommended_Payload, "");
	if(payloadText == "")
	{
		out.put("error", "empty Recommended_Payload");
		return out;
	}
	// Expected payload: JSON map of CRM API names → values. Example:
	// {"Policy_Status":"Active","Premium":1200.00}
	payload = payloadText.toMap();
	resp = zoho.crm.updateRecord("Policies", rec.CRM_Policy_ID, payload);
	rec.Approved_To_Push=false;
	rec.Sync_Status="Pending";
	thisapp.recon.writeStatusHistory(policyID, rec.Policy_Status, rec.Policy_Status, "Creator");
	out.put("ok", true);
	out.put("crm_response", resp);
	return out;
}


